CREATE TABLE IF NOT EXISTS attendance_events (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL, location_id INTEGER NOT NULL, school_date TEXT NOT NULL, checked_at TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('QR','MANUAL')), confirmed_by TEXT, is_arrival INTEGER NOT NULL CHECK(is_arrival IN (0,1)), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(location_id) REFERENCES attendance_locations(id));
